import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import * as api from '../api';
import { t } from '../util';
import MomentCard from './MomentCard';
import { loadComposer } from '../composerLoader';

/** Replies nest this deep; anything deeper is shown at this level, in order. */
export const MAX_DEPTH = 3;
/**
 * A moment's replies: newest or most-reacted first, twenty threads at a
 * time, each thread nested to three levels.
 */
export default class Replies extends Component {
  replies = [];
  sort = 'recent';
  next = null;
  loading = true;
  replyingTo = null;
  Composer = null;
  asked = 0;
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
    if (this.attrs.moment.can.reply) loadComposer().then(C => (this.Composer = C, m.redraw()));
  }
  load(more) {
    if (more === void 0) {
      more = false;
    }
    this.loading = true;
    const ask = ++this.asked;
    api.getReplies(this.attrs.moment.id, this.sort, more ? this.next : null).then(page => {
      if (ask !== this.asked) return;
      this.replies = more ? [...this.replies, ...page.data] : page.data;
      this.next = page.meta.next;
      this.loading = false;
      m.redraw();
      if (this.attrs.focus && !more) requestAnimationFrame(() => document.getElementById(`moment-${this.attrs.focus}`)?.scrollIntoView({
        block: 'center'
      }));
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
  children(parentId) {
    return this.replies.filter(r => r.parentId === parentId);
  }

  /** Everything under a reply, oldest first, for the flattened deepest level. */
  descendants(parentId) {
    const out = [];
    const walk = id => this.children(id).forEach(child => {
      out.push(child);
      walk(child.id);
    });
    walk(parentId);
    return out.sort((a, b) => a.id - b.id);
  }
  view() {
    const mo = this.attrs.moment;
    const heads = this.children(mo.id);
    return m("section", {
      className: "MomentReplies",
      "aria-label": t('replies.label')
    }, mo.can.reply && this.Composer ? m(this.Composer, {
      config: this.attrs.config,
      parentId: mo.id,
      compact: true,
      onposted: r => this.added(r)
    }) : mo.isLocked ? m("p", {
      className: "MomentReplies-locked"
    }, m("i", {
      className: "fas fa-lock",
      "aria-hidden": "true"
    }), " ", t('replies.locked')) : null, heads.length > 1 || this.sort === 'top' ? m("div", {
      className: "MomentReplies-sort",
      role: "group",
      "aria-label": t('replies.sort')
    }, ['recent', 'top'].map(sort => m(Button, {
      className: 'Button Button--flat Button--small' + (this.sort === sort ? ' active' : ''),
      "aria-pressed": this.sort === sort ? 'true' : 'false',
      onclick: () => {
        this.sort = sort;
        this.load();
      }
    }, t(`replies.${sort}`)))) : null, m("div", {
      className: "MomentReplies-list"
    }, heads.map(r => this.node(r, 1))), this.loading ? m(LoadingIndicator, {
      size: "small"
    }) : null, !this.loading && this.next ? m(Button, {
      className: "Button Button--link MomentReplies-more",
      onclick: () => this.load(true)
    }, t('replies.more')) : null);
  }
  node(reply, depth) {
    const nested = depth >= MAX_DEPTH ? this.descendants(reply.id) : this.children(reply.id);
    return m("div", {
      className: `MomentReply MomentReply--depth${Math.min(depth, MAX_DEPTH)}`,
      key: reply.id
    }, m(MomentCard, {
      moment: reply,
      config: this.attrs.config,
      thread: "none",
      focus: this.attrs.focus,
      onreply: r => {
        this.replyingTo = this.replyingTo === r.id ? null : r.id;
      },
      onchange: r => this.replace(r),
      ondelete: id => this.removed(id)
    }), this.replyingTo === reply.id && this.Composer ? m("div", {
      className: "MomentReply-composer"
    }, m(this.Composer, {
      config: this.attrs.config,
      parentId: reply.id,
      compact: true,
      autofocus: true,
      placeholder: String(t('composer.reply_to', {
        name: api.user(reply.userId)?.displayName() || ''
      })),
      oncancel: () => this.replyingTo = null,
      onposted: r => this.added(r)
    })) : null, nested.length ? m("div", {
      className: "MomentReply-children"
    }, depth >= MAX_DEPTH ? nested.map(child => this.flat(child)) : nested.map(child => this.node(child, depth + 1))) : null);
  }
  flat(reply) {
    return m("div", {
      className: `MomentReply MomentReply--depth${MAX_DEPTH} MomentReply--flat`,
      key: reply.id
    }, m(MomentCard, {
      moment: reply,
      config: this.attrs.config,
      thread: "none",
      focus: this.attrs.focus,
      onreply: r => this.replyingTo = this.replyingTo === r.id ? null : r.id,
      onchange: r => this.replace(r),
      ondelete: id => this.removed(id)
    }), this.replyingTo === reply.id && this.Composer ? m("div", {
      className: "MomentReply-composer"
    }, m(this.Composer, {
      config: this.attrs.config,
      parentId: reply.id,
      compact: true,
      autofocus: true,
      oncancel: () => this.replyingTo = null,
      onposted: r => this.added(r)
    })) : null);
  }
  added(reply) {
    this.replyingTo = null;
    // A new thread goes on top (newest first); a reply inside one goes last (oldest first).
    this.replies = reply.parentId === this.attrs.moment.id ? [reply, ...this.replies] : [...this.replies, reply];
    this.attrs.onchange?.(this.attrs.moment.replyCount + 1);
  }
  replace(reply) {
    this.replies = this.replies.map(r => r.id === reply.id ? reply : r);
  }
  removed(id) {
    const gone = new Set([id, ...this.descendants(id).map(r => r.id)]);
    this.replies = this.replies.filter(r => !gone.has(r.id));
    this.attrs.onchange?.(Math.max(0, this.attrs.moment.replyCount - gone.size));
    app.alerts.show({
      type: 'success'
    }, t('card.deleted'));
  }
}
flarum.reg.add('ernestdefoe-moments', 'forum/components/Replies', Replies);