/** A feed's moments, kept outside the component so the composer above it can add to it. */
export class FeedState {
  items = [];
  next = null;
  loading = false;
  loaded = false;
  fresh = 0;
  prepend(moment) {
    this.items = [moment, ...this.items.filter(x => x.id !== moment.id)];
  }
}
