import UserPage from 'flarum/forum/components/UserPage';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import * as api from '../api';
import { t } from '../util';
import Feed from '../components/Feed';

/** A member's Moments tab: their moments and reposts, each through the privacy rule. */
export default class UserMomentsPage extends UserPage {
  config = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
    api.loadConfig().then(config => {
      this.config = config;
      m.redraw();
    });
  }
  show(user) {
    super.show(user);
  }
  content() {
    if (!this.user || !this.config) return m(LoadingIndicator, null);
    return m("div", {
      className: "UserMomentsPage MomentsPage"
    }, m(Feed, {
      key: this.user.id(),
      filter: {
        feed: 'user',
        user: this.user.id()
      },
      config: this.config,
      empty: m(Placeholder, {
        text: t('user.empty', {
          name: this.user.displayName()
        })
      })
    }));
  }
}
flarum.reg.add('ernestdefoe-moments', 'forum/pages/UserMomentsPage', UserMomentsPage);